import React, { useEffect } from 'react';
import { autoWebViewJs } from '@droid/android';
import { useProxyWatch, useTranslation, JvmStaticCompleteEvent, publicRuntimeConfig, AppEnv } from '@fanfanlo';
import { Box, Button } from '@mui/material';
import { user } from '@app/model';

const eventOnGoogleLoginSuccess = 'AndroidGoogleLoginSuccess';
interface GoogleLoginEventDetail {
  idToken: string;
}
export function GoogleLoginButton() {
  const { t } = useTranslation('homepage/components/Login/content');
  const handleGoogleLogin = () => {
    console.log('Initiating Android Google Login...');
    try {
      let script = `
        com.fanfanlo.droid.auth.FirebaseAuthManager.startGoogleLogin();
      `;
      // if (publicRuntimeConfig.env == AppEnv.Prod) {
      //   // 调用 Android 的 FirebaseAuthManager.startGoogleLogin()
      //   // 不需要参数，只负责触发登录
      //   script = `
      //   com.fanfanlo.droid.auth.FirebaseAuthManager.startGoogleLogin();
      // `;
      // } else {
      //   // 测试快速登陆
      //   script = `
      // com.fanfanlo.droid.remote.user.UserApi.testLoginByFirebaseWithInfo()`;
      // }

      autoWebViewJs.callScript(script);
    } catch (error) {
      console.error('Google Login initiation failed:', error);
    }
  };
  useEffect(() => {
    function onGoogleLoginSuccess(event: any) {
      console.log('Google Login Successful, event data:', event.detail);
      console.log('Google Login Successful, event data3:', event);
      console.log('Google Login Successful, event data2:', JSON.stringify(event.detail));
      const detail = event.detail as JvmStaticCompleteEvent<GoogleLoginEventDetail>;
      if (!detail || !detail.data || !detail.data.idToken) {
        console.error('Google login event detail invalid', detail);
        return;
      }
      console.log('detail=', detail);
      user.setUserToken(detail.data.idToken);
      user.signin();
    }
    window.addEventListener(eventOnGoogleLoginSuccess, onGoogleLoginSuccess);
    return () => {
      window.removeEventListener(eventOnGoogleLoginSuccess, onGoogleLoginSuccess);
    };
  }, []);
  return <Button onClick={handleGoogleLogin}>{t('GoogleLoginButton.name')}</Button>;
}

export function LoginButtonBox() {
  const [userToken] = useProxyWatch(user, 'data.storeData.user_token', user.data.storeData.user_token);
  if (userToken) {
    return <></>;
  }
  return (
    <Box>
      <GoogleLoginButton />
    </Box>
  );
}
